type StoreLocation={id:string;codigo:string;nombre:string;regionId:string|null};
type TransferRow={id:string;date:string;exportDate:string;deadline:string|null;remaining:number|null;deadlineStatus:"VENCIDA"|"HOY"|"MANANA"|"A_TIEMPO"|"SIN_FECHA";store:string;tiendaId:string;tiendaNombre:string;units:number;description:string;type:TransferType};
type CaseRow={id:string;createdAt:string|Date;sucursal:string;transferencia:string;codigoBarra:string;tipoError:string;cantidadErrada:number;resuelto:boolean;ajustado:boolean;grupoReporteId:string|null;claveCruce:string|null};
type ReportDetail={id:string;tipo:"PRODUCTO"|"CODIGO_NO_REGISTRADO";codigoBarra:string;descripcion:string|null;tipoError:string;cantidad:number;motivo:string|null;submotivo:string|null;detalle:string|null;observacionAdmin:string|null;resuelto:boolean;codigoBarraTransferencia?:string|null;cantidadPaquete?:number|null};
type ReportRow={id:string;createdAt:string|Date;transferencia:string;tienda:string;sinIncidencias:boolean;finalizado:boolean;detalles:ReportDetail[]};
type Dashboard={stores:StoreLocation[];metrics:{pendingTransfers:number;openCases:number;urgentTransfers:number};dateReliable:boolean;transfers:TransferRow[];recent:CaseRow[];reports:ReportRow[]};
type Product={id:string;codigoBarra:string;referencia:string|null;descripcion:string|null;marca:string|null;activo:boolean;inventarios:{existencia:string;bodegaProductoId:string|null;bodegaProducto:{nombre:string}|null}[]};
