declare global {interface Window {BarcodeDetector?:new(options?:{formats?:string[]})=>{detect(source:ImageBitmapSource):Promise<{rawValue:string}[]>}}}

class StoreApiError extends Error {constructor(message:string,public status:number,public code?:string){super(message)}}
async function api<T>(path:string,options?:RequestInit){const response=await fetch(`/api/tienda${path}`,{cache:"no-store",...options});const body=await response.json();if(!response.ok||!body.ok)throw new StoreApiError(body.error?.message??"No se pudo completar la operación.",response.status,body.error?.code);return body.data as T;}
const dateTime=(value:string|Date)=>new Date(value).toLocaleString("es-VE",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"});

function Scanner({onCode,close}:{onCode:(code:string)=>void;close:()=>void}){
  const video=useRef<HTMLVideoElement>(null),[error,setError]=useState("");
  useEffect(()=>{let stream:MediaStream|undefined,timer=0,active=true;const start=async()=>{try{if(!window.BarcodeDetector)throw new Error("La cámara de este navegador no reconoce códigos. Use la entrada manual.");stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}}});if(!video.current)return;video.current.srcObject=stream;await video.current.play();const detector=new window.BarcodeDetector({formats:["ean_13","ean_8","code_128","upc_a","upc_e"]});const scan=async()=>{if(!active||!video.current)return;try{const codes=await detector.detect(video.current);if(codes[0]?.rawValue){onCode(codes[0].rawValue);return;}}catch{}timer=window.setTimeout(scan,250)};void scan();}catch(e){setError(e instanceof Error?e.message:"No se pudo abrir la cámara.")}};void start();return()=>{active=false;window.clearTimeout(timer);stream?.getTracks().forEach(track=>track.stop())}},[onCode]);
  return <div className="fixed inset-0 z-50 grid place-items-center bg-brand-night/90 p-4"><div className="w-full max-w-md rounded-3xl bg-card p-4 shadow-2xl"><div className="mb-3 flex items-center justify-between"><h3 className="font-semibold">Escanear código</h3><Button variant="ghost" onClick={close}>Cerrar</Button></div>{error?<div className="rounded-2xl border border-warning-300 bg-warning-50 p-5 text-sm text-warning-900 dark:border-warning-800 dark:bg-warning-950/40 dark:text-warning-200">{error}</div>:<video ref={video} muted playsInline className="aspect-[3/4] w-full rounded-2xl bg-black object-cover"/>}</div></div>;
}

function TransferCard({item,onSuccess}:{item:TransferRow;onSuccess?:()=>Promise<void>}){
  const [busy,setBusy]=useState(false),[confirmOpen,setConfirmOpen]=useState(false);const status={VENCIDA:["Vencida","bg-danger-100 text-danger-800 dark:bg-danger-950/40 dark:text-danger-200"],HOY:["Vence hoy","bg-warning-100 text-warning-900 dark:bg-warning-950/40 dark:text-warning-200"],MANANA:["Vence mañana","bg-warning-100 text-warning-900 dark:bg-warning-950/40 dark:text-warning-200"],A_TIEMPO:[`${item.remaining} días hábiles`,`bg-success-100 text-success-800`],SIN_FECHA:["Sin fecha de exportación","bg-muted text-muted-foreground"]}[item.deadlineStatus];
  const typeTone={NORMAL:"border-border bg-muted text-muted-foreground",CORRECCION:"border-violet-200 bg-violet-100 text-violet-800",ROTACION:"border-info-200 bg-info-100 text-info-800"}[item.type];
  async function success(){if(!onSuccess)return;setBusy(true);try{await api("?accion=sin-incidencias",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({solicitudId:crypto.randomUUID(),tiendaId:item.tiendaId,transferencia:item.id})});setConfirmOpen(false);toast.success("Transferencia registrada sin incidencias.");await onSuccess()}catch(e){toast.error(e instanceof Error?e.message:"No se pudo registrar.")}finally{setBusy(false)}}
  return <><article className="pdmc-surface group rounded-3xl border bg-card p-5 shadow-sm transition hover:-translate-y-0.5 hover:border-primary/30 hover:shadow-lg"><div className="flex items-start justify-between gap-3"><div><Badge variant="outline" className={typeTone}>{transferTypeLabel[item.type]}</Badge><p className="mt-3 font-mono text-2xl font-bold">#{item.id}</p><p className="mt-1 text-sm font-medium">{item.tiendaNombre}</p></div><Badge className={status[1]}>{status[0]}</Badge></div><div className="mt-5 rounded-2xl bg-muted/50 p-3 text-sm"><p className="text-xs text-muted-foreground">Unidades</p><p className="text-lg font-bold">{item.units.toLocaleString("es-VE")}</p>{item.description&&<><p className="mt-3 text-xs text-muted-foreground">Descripción</p><p className="mt-1 font-medium">{item.description}</p></>}</div>{onSuccess&&<Button className="mt-4 w-full" variant="outline" disabled={busy} onClick={()=>setConfirmOpen(true)}><Check/>Recibida sin incidencias</Button>}</article><AlertDialog open={confirmOpen} onOpenChange={setConfirmOpen}><AlertDialogContent><AlertDialogHeader><AlertDialogMedia className="bg-success-100 text-success-700 dark:bg-success-950/40 dark:text-success-200"><Check/></AlertDialogMedia><AlertDialogTitle>Confirmar recepción completa</AlertDialogTitle><AlertDialogDescription>La transferencia #{item.id} ({transferTypeLabel[item.type]}) se marcará como recibida sin faltantes, sobrantes ni otras incidencias.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={busy}>Volver</AlertDialogCancel><AlertDialogAction disabled={busy} onClick={event=>{event.preventDefault();void success()}}>{busy?"Registrando…":"Sí, confirmar recepción"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>
}

export function StorePanel({user,initialData}:{user:UsuarioSesion;initialData:Dashboard}){
  const [view,setView]=useState<View>("inicio"),[data,setData]=useState<Dashboard|null>(initialData),[loading,setLoading]=useState(false),[error,setError]=useState("");
  const [unknownSeed,setUnknownSeed]=useState<UnknownSeed|null>(null);
  const [reportDrafts,setReportDrafts]=useState<ReportDraft[]>([]);
  const [reviewRequest,setReviewRequest]=useState(0);
  const load=useCallback(async()=>{setLoading(true);setError("");try{setData(await api<Dashboard>("?accion=inicio"));}catch(e){setError(e instanceof Error?e.message:"No se pudo cargar.")}finally{setLoading(false)}},[]);
  return <div className="store-workspace workspace min-h-screen bg-background pb-32"><SessionWatch/><header className="sticky top-3 z-30 mx-auto max-w-5xl px-3"><div className="store-topbar flex h-[4.5rem] items-center gap-3 px-3 sm:px-4"><PdmcMark title="PDMC" className="size-11 drop-shadow-[0_8px_18px_rgba(14,22,48,.25)]"/><div className="min-w-0 flex-1"><p className="text-[10px] font-bold uppercase tracking-[.16em] text-primary">Portal de tienda</p><p className="truncate text-base font-bold sm:text-lg">{data?.stores.map(item=>item.nombre).join(" · ")||"Tienda"}</p><p className="truncate text-[11px] text-muted-foreground">Sesión de {user.nombre}</p></div><ThemeToggle compact/><Button asChild variant="ghost" size="icon" className="rounded-xl border bg-background/50"><Link href="/cambiar-contrasena" aria-label="Ajustes de la cuenta"><Settings/></Link></Button></div></header><main className="mx-auto max-w-5xl px-4 pb-4 pt-7 sm:px-6 sm:pt-9">{loading?<div className="grid min-h-[55vh] place-items-center"><div className="grid place-items-center gap-3 text-sm text-muted-foreground"><RefreshCw className="size-7 animate-spin text-primary"/>Actualizando la tienda…</div></div>:error?<div className="rounded-3xl border border-danger-300 bg-danger-50 p-6 text-danger-800 shadow-sm dark:border-danger-800 dark:bg-danger-950/40 dark:text-danger-200"><p className="font-semibold">No pudimos cargar la tienda</p><p className="mt-1 text-sm">{error}</p><Button className="mt-4" onClick={()=>void load()}>Reintentar</Button></div>:data&&<>{view==="inicio"&&<HomeView data={data} go={setView}/>} {view==="transferencias"&&<TransfersView data={data} done={load}/>} {view==="casos"&&<CasesView rows={data.recent} reports={data.reports}/>} {view==="pedidos"&&<OrdersView data={data} userId={user.id}/>} <div className={view==="reportar"?"":"hidden"}><ReportFlow key={reviewRequest} data={data} drafts={reportDrafts} setDrafts={setReportDrafts} reviewRequest={reviewRequest} openUnknown={seed=>{setUnknownSeed(seed);setView("codigo")}} done={async finish=>{if(finish){setReportDrafts([]);setUnknownSeed(null)}await load();if(finish)setView("inicio")}}/></div> {unknownSeed&&<div className={view==="codigo"?"":"hidden"}><UnknownCodeFlow key={`${unknownSeed.storeId}:${unknownSeed.transfer}:${unknownSeed.code}:${unknownSeed.editId??"new"}`} data={data} seed={unknownSeed} drafts={reportDrafts} setDrafts={setReportDrafts} backToReport={()=>setView("reportar")} reviewReport={()=>{setReviewRequest(value=>value+1);setView("reportar")}}/></div>}</>}</main><nav className="store-liquid-nav fixed inset-x-3 bottom-3 z-40 mx-auto max-w-xl p-1.5 pb-[max(.375rem,env(safe-area-inset-bottom))]" aria-label="Navegación de tienda"><div className="grid grid-cols-4 gap-1">{[["inicio","Inicio",Home],["reportar","Reportar",Plus],["transferencias","Pendientes",Truck],["casos","Historial",ClipboardList]] .map(([id,label,Icon])=><button key={String(id)} aria-current={view===id?"page":undefined} onClick={()=>setView(id as View)} className={`relative flex min-h-14 flex-col items-center justify-center gap-1 rounded-[1.15rem] px-1 text-[10px] font-bold transition-all sm:text-[11px] ${view===id?"bg-primary text-primary-foreground shadow-lg shadow-primary/20":"text-muted-foreground hover:bg-background/70 hover:text-foreground"}`}><Icon className={`size-5 transition-transform ${view===id?"-translate-y-0.5":""}`}/>{label as string}{id==="reportar"&&reportDrafts.length>0&&<span className={`absolute right-2 top-1.5 grid min-w-4 place-items-center rounded-full px-1 text-[9px] ${view===id?"bg-white text-primary":"bg-success-500 text-white"}`}>{reportDrafts.length}</span>}{id==="transferencias"&&(data?.metrics.pendingTransfers??0)>0&&<span className={`absolute right-2 top-1.5 grid min-w-4 place-items-center rounded-full px-1 text-[9px] ${view===id?"bg-white text-primary":"bg-warning-500 text-white"}`}>{Math.min(99,data?.metrics.pendingTransfers??0)}</span>}</button>)}</div></nav><Toaster richColors position="top-center"/></div>;
}

function HomeView({data,go}:{data:Dashboard;go:(view:View)=>void}){return <div className="space-y-6"><section className="store-hero overflow-hidden"><div className="relative z-10 grid gap-7 lg:grid-cols-[1fr_auto] lg:items-end"><div><Badge className="border-white/15 bg-white/10 text-white"><Store/>Recepción de mercancía</Badge><h1 className="mt-4 max-w-2xl text-3xl font-black tracking-tight sm:text-4xl">Recibe, revisa y reporta con claridad.</h1><p className="mt-3 max-w-xl text-sm leading-6 text-white/70">Selecciona una transferencia, registra todas las diferencias y confirma el resultado desde un solo flujo.</p></div><Button size="lg" className="h-13 rounded-2xl bg-brand-glow px-7 font-bold text-brand-deep shadow-xl shadow-black/15 hover:brightness-110" onClick={()=>go("reportar")}><Plus/>Iniciar reporte</Button></div><div className="relative z-10 mt-7 grid gap-2 sm:grid-cols-3"><StoreHeroStat label="Pendientes" value={data.metrics.pendingTransfers} icon={Truck}/><StoreHeroStat label="Casos abiertos" value={data.metrics.openCases} icon={ClipboardList}/><StoreHeroStat label="Atención prioritaria" value={data.metrics.urgentTransfers} icon={AlertTriangle}/></div></section><div className="grid gap-4 md:grid-cols-[1.15fr_.85fr]"><button onClick={()=>go("transferencias")} className="store-action-card group text-left"><div className="flex items-start justify-between"><span className="grid size-12 place-items-center rounded-2xl bg-warning-100 text-warning-800 dark:bg-warning-950/50 dark:text-warning-200"><Truck className="size-6"/></span><ArrowRight className="size-5 text-muted-foreground transition group-hover:translate-x-1 group-hover:text-primary"/></div><p className="mt-6 text-xs font-bold uppercase tracking-[.15em] text-muted-foreground">Por completar</p><p className="mt-1 text-4xl font-black tabular-nums">{data.metrics.pendingTransfers.toLocaleString("es-VE")}</p><p className="mt-2 text-sm text-muted-foreground">Transferencias esperando confirmación o reporte.</p></button><button onClick={()=>go("casos")} className="store-action-card group text-left"><div className="flex items-start justify-between"><span className="grid size-12 place-items-center rounded-2xl bg-info-100 text-info-800 dark:bg-info-950/50 dark:text-info-200"><ClipboardList className="size-6"/></span><ArrowRight className="size-5 text-muted-foreground transition group-hover:translate-x-1 group-hover:text-primary"/></div><p className="mt-6 text-xs font-bold uppercase tracking-[.15em] text-muted-foreground">Seguimiento</p><p className="mt-1 text-4xl font-black tabular-nums">{data.metrics.openCases.toLocaleString("es-VE")}</p><p className="mt-2 text-sm text-muted-foreground">Inconsistencias que siguen en proceso.</p></button></div>{data.metrics.urgentTransfers>0&&<button onClick={()=>go("transferencias")} className="flex w-full items-center gap-4 rounded-3xl border border-danger-200 bg-gradient-to-r from-danger-50 to-orange-50 p-4 text-left text-danger-950 shadow-sm dark:border-danger-900 dark:from-danger-950/40 dark:to-orange-950/20 dark:text-danger-100"><span className="grid size-11 place-items-center rounded-2xl bg-danger-100 text-danger-700 dark:bg-danger-900/60 dark:text-danger-200"><AlertTriangle className="size-5"/></span><div className="min-w-0 flex-1"><p className="font-bold">{data.metrics.urgentTransfers} transferencias requieren atención</p><p className="text-sm opacity-70">Revise las fechas y complete el reporte pendiente.</p></div><ArrowRight className="size-5 shrink-0"/></button>}{!data.dateReliable&&data.transfers.length>0&&<div className="rounded-2xl border bg-card/80 p-4 text-sm text-muted-foreground shadow-sm">La fuente todavía no incluye una fecha de exportación confiable; el vencimiento se mostrará cuando esté disponible.</div>}<section className="rounded-[1.75rem] border bg-card/90 p-5 shadow-sm sm:p-6"><div className="mb-5 flex items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Actividad reciente</p><h2 className="mt-1 text-xl font-bold">Últimos reportes</h2></div><Button variant="ghost" size="sm" onClick={()=>go("casos")}>Ver historial<ArrowRight/></Button></div><ReportHistory rows={data.reports.slice(0,4)}/>{!data.reports.length&&<p className="rounded-2xl border border-dashed bg-muted/20 p-7 text-center text-sm text-muted-foreground">Todavía no hay reportes registrados para esta tienda.</p>}</section></div>}

function StoreHeroStat({label,value,icon:Icon}:{label:string;value:number;icon:typeof Truck}){return <div className="flex items-center gap-3 rounded-2xl border border-white/10 bg-white/[.07] px-4 py-3 backdrop-blur-md"><Icon className="size-5 text-brand-mist"/><div><p className="text-xl font-black tabular-nums text-white">{value.toLocaleString("es-VE")}</p><p className="text-[10px] font-bold uppercase tracking-wider text-white/55">{label}</p></div></div>}

function TransfersView({data,done}:{data:Dashboard;done:()=>Promise<void>}){return <div className="space-y-5"><section className="store-section-head"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Recepción pendiente</p><h1 className="mt-1 text-2xl font-black sm:text-3xl">Transferencias por confirmar</h1><p className="mt-2 max-w-2xl text-sm text-muted-foreground">Confirma las entregas completas aquí. Si encuentras cualquier diferencia, abre Reportar y agrega todos los productos involucrados.</p></div><span className="grid size-14 place-items-center rounded-2xl bg-warning-100 text-2xl font-black text-warning-800 dark:bg-warning-950/50 dark:text-warning-200">{data.transfers.length}</span></section>{!data.dateReliable&&<div className="rounded-2xl border border-warning-200 bg-warning-50 p-4 text-sm text-warning-900 dark:border-warning-900 dark:bg-warning-950/30 dark:text-warning-100">La consulta no contiene una fecha de exportación confiable. El vencimiento aparecerá cuando la fuente incluya ese dato.</div>}<div className="grid gap-4 md:grid-cols-2">{data.transfers.map(item=><TransferCard key={`${item.tiendaId}:${item.id}`} item={item} onSuccess={done}/>)}</div>{!data.transfers.length&&<div className="rounded-3xl border border-dashed bg-card/60 p-12 text-center"><span className="mx-auto grid size-14 place-items-center rounded-full bg-success-100 text-success-700 dark:bg-success-950/40 dark:text-success-200"><Check className="size-7"/></span><p className="mt-4 text-lg font-bold">Todo está reportado</p><p className="mt-1 text-sm text-muted-foreground">No hay transferencias pendientes para esta tienda.</p></div>}</div>}

function OrdersView({data,userId}:{data:Dashboard;userId:string}){
  const storageKey=`pdmc:pedido:${userId}`,[catalog,setCatalog]=useState<CatalogPayload|null>(null),[orders,setOrders]=useState<StoreOrder[]>([]),[query,setQuery]=useState(""),[line,setLine]=useState(""),[brand,setBrand]=useState(""),[page,setPage]=useState(1),[cart,setCart]=useState<Record<string,{product:CatalogProduct;quantity:number}>>({}),[storeId,setStoreId]=useState(data.stores[0]?.id??""),[notes,setNotes]=useState(""),[busy,setBusy]=useState(false),[error,setError]=useState(""),[confirm,setConfirm]=useState(false);const take=24;
  useEffect(()=>{const timer=setTimeout(()=>{try{const saved=localStorage.getItem(storageKey);if(saved){const draft=JSON.parse(saved);setCart(draft.cart??{});setStoreId(draft.storeId??data.stores[0]?.id??"");setNotes(draft.notes??"")}}catch{}},0);return()=>clearTimeout(timer)},[storageKey,data.stores]);
  useEffect(()=>{localStorage.setItem(storageKey,JSON.stringify({cart,storeId,notes}))},[storageKey,cart,storeId,notes]);
  const loadOrders=useCallback(async()=>{try{setOrders(await api<StoreOrder[]>("?accion=pedidos"))}catch(e){setError(e instanceof Error?e.message:"No se pudieron cargar los pedidos.")}},[]);
  useEffect(()=>{const timer=setTimeout(()=>void loadOrders(),0);return()=>clearTimeout(timer)},[loadOrders]);
  useEffect(()=>{const controller=new AbortController(),timer=setTimeout(()=>{const params=new URLSearchParams({accion:"catalogo-pedidos",q:query,linea:line,marca:brand,skip:String((page-1)*take),take:String(take)});api<CatalogPayload>(`?${params}`,{signal:controller.signal}).then(setCatalog).catch(e=>{if(!controller.signal.aborted)setError(e instanceof Error?e.message:"No se pudo cargar el catálogo.")})},250);return()=>{clearTimeout(timer);controller.abort()}},[query,line,brand,page]);
  const items=Object.values(cart),units=items.reduce((sum,item)=>sum+item.quantity,0),pages=Math.max(1,Math.ceil((catalog?.total??0)/take));
  const setQuantity=(product:CatalogProduct,quantity:number)=>setCart(previous=>{if(quantity<=0){const next={...previous};delete next[product.id];return next}return {...previous,[product.id]:{product,quantity:Math.min(9999,quantity)}}});
  const send=async()=>{setBusy(true);setError("");try{await api<StoreOrder>("?accion=pedidos",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({tiendaId:storeId,observaciones:notes.trim()||undefined,items:items.map(item=>({productoId:item.product.id,cantidad:item.quantity}))})});setCart({});setNotes("");localStorage.removeItem(storageKey);setConfirm(false);toast.success("Pedido enviado correctamente.");await loadOrders()}catch(e){setError(e instanceof Error?e.message:"No se pudo enviar el pedido.")}finally{setBusy(false)}};
  return <div className="space-y-5"><section className="module-hero"><div className="relative z-10 flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><Badge className="border-white/15 bg-white/10 text-white">Nuevo módulo</Badge><h1 className="mt-3 text-3xl font-bold">Pedidos de mercancía</h1><p className="mt-2 max-w-xl text-sm text-white/70">Arma un pedido con productos activos, filtrando por línea y marca.</p></div><div className="rounded-2xl border border-white/15 bg-white/10 px-5 py-3 text-white"><p className="text-xs text-white/60">Pedido actual</p><p className="text-xl font-bold">{items.length} productos · {units} unidades</p></div></div></section>
    <div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_320px]"><div className="space-y-4"><section className="pdmc-surface rounded-2xl border bg-card p-4 shadow-sm"><div className="grid gap-3 sm:grid-cols-2"><div className="relative sm:col-span-2"><Search className="absolute left-3 top-3 size-4 text-muted-foreground"/><Input className="pl-9" placeholder="Código, referencia o descripción" value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}}/></div><Select value={line||"__all__"} onValueChange={value=>{setLine(value==="__all__"?"":value);setBrand("");setPage(1)}}><SelectTrigger><SelectValue placeholder="Todas las líneas"/></SelectTrigger><SelectContent><SelectItem value="__all__">Todas las líneas</SelectItem>{catalog?.lineas.map(value=><SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select><Select value={brand||"__all__"} onValueChange={value=>{setBrand(value==="__all__"?"":value);setPage(1)}}><SelectTrigger><SelectValue placeholder="Todas las marcas"/></SelectTrigger><SelectContent><SelectItem value="__all__">Todas las marcas</SelectItem>{catalog?.marcas.map(value=><SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></div></section>
      <div className="grid gap-3 sm:grid-cols-2">{catalog?.rows.map(product=>{const selected=cart[product.id];return <article key={product.id} className={`rounded-2xl border bg-card p-4 shadow-sm transition ${selected?"border-primary ring-1 ring-primary/20":"hover:border-primary/30"}`}><div className="flex items-start justify-between gap-3"><div className="min-w-0"><Badge variant="outline" className="max-w-full truncate">{product.marca||"Sin marca"}</Badge><h3 className="mt-3 line-clamp-2 font-semibold">{product.descripcion||product.referencia||product.codigoBarra}</h3><p className="mt-1 font-mono text-xs text-muted-foreground">{product.codigoBarra}</p></div>{selected&&<Badge>{selected.quantity}</Badge>}</div><p className="mt-3 truncate text-xs text-muted-foreground">{product.linea||"Sin línea"} · {product.referencia||"Sin referencia"}</p>{selected?<div className="mt-4 flex items-center gap-2"><Button size="icon" variant="outline" onClick={()=>setQuantity(product,selected.quantity-1)}><Minus/></Button><Input aria-label={`Cantidad de ${product.codigoBarra}`} className="text-center font-bold" type="number" min={1} max={9999} value={selected.quantity} onChange={e=>setQuantity(product,Number(e.target.value))}/><Button size="icon" variant="outline" onClick={()=>setQuantity(product,selected.quantity+1)}><Plus/></Button></div>:<Button className="mt-4 w-full" variant="outline" onClick={()=>setQuantity(product,1)}><Plus/>Agregar</Button>}</article>})}</div>{catalog&&!catalog.rows.length&&<div className="rounded-2xl border border-dashed p-10 text-center text-sm text-muted-foreground">No hay productos para estos filtros.</div>}<div className="flex items-center justify-between text-sm"><span className="text-muted-foreground">{catalog?.total??0} productos</span><div className="flex gap-2"><Button size="sm" variant="outline" disabled={page<=1} onClick={()=>setPage(value=>value-1)}>Anterior</Button><Button size="sm" variant="outline" disabled={page>=pages} onClick={()=>setPage(value=>value+1)}>Siguiente</Button></div></div></div>
      <aside className="space-y-4 lg:sticky lg:top-24 lg:self-start"><section className="pdmc-surface rounded-2xl border bg-card p-4 shadow-sm"><div className="flex items-center justify-between"><div><p className="text-xs font-semibold uppercase tracking-widest text-primary">Resumen</p><h2 className="mt-1 font-bold">Pedido actual</h2></div><ShoppingCart className="size-5 text-primary"/></div>{data.stores.length>1&&<label className="mt-4 grid gap-1.5 text-sm font-medium">Tienda<Select value={storeId} onValueChange={setStoreId}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{data.stores.map(store=><SelectItem key={store.id} value={store.id}>{store.nombre}</SelectItem>)}</SelectContent></Select></label>}<div className="mt-4 max-h-72 space-y-2 overflow-y-auto">{items.map(item=><div key={item.product.id} className="flex items-center gap-2 rounded-xl bg-muted/40 p-3"><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{item.product.referencia||item.product.codigoBarra}</p><p className="truncate text-xs text-muted-foreground">{item.product.marca||"Sin marca"} · {item.quantity} unidades</p></div><Button size="icon" variant="ghost" onClick={()=>setQuantity(item.product,0)}><Trash2 className="size-4"/></Button></div>)}{!items.length&&<p className="rounded-xl border border-dashed p-5 text-center text-sm text-muted-foreground">Agrega productos del catálogo.</p>}</div><Textarea className="mt-4" rows={3} maxLength={1000} placeholder="Observación general (opcional)" value={notes} onChange={e=>setNotes(e.target.value)}/>{error&&<p className="mt-3 rounded-xl bg-danger-50 p-3 text-sm text-danger-800 dark:bg-danger-950/40 dark:text-danger-200">{error}</p>}<Button className="mt-4 w-full" disabled={!items.length||!storeId||busy} onClick={()=>setConfirm(true)}><Send/>Revisar y enviar</Button></section>
        {orders.length>0&&<section className="pdmc-surface rounded-2xl border bg-card p-4 shadow-sm"><h2 className="font-bold">Pedidos recientes</h2><div className="mt-3 space-y-2">{orders.slice(0,5).map(order=><div key={order.id} className="rounded-xl border p-3"><div className="flex items-center justify-between gap-2"><p className="font-mono text-xs font-bold">{order.codigo}</p><Badge variant="outline">{order.estado.replaceAll("_"," ")}</Badge></div><p className="mt-1 text-xs text-muted-foreground">{order.items.length} productos · {order.items.reduce((sum,item)=>sum+item.cantidadSolicitada,0)} unidades · {dateTime(order.createdAt)}</p></div>)}</div></section>}
      </aside></div><AlertDialog open={confirm} onOpenChange={value=>!busy&&setConfirm(value)}><AlertDialogContent><AlertDialogHeader><AlertDialogMedia className="bg-primary/10 text-primary"><ShoppingCart/></AlertDialogMedia><AlertDialogTitle>Enviar pedido a bodega</AlertDialogTitle><AlertDialogDescription>Se enviarán {items.length} productos y {units} unidades para {data.stores.find(store=>store.id===storeId)?.nombre}. Podrás consultar su estado en esta misma sección.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={busy}>Seguir editando</AlertDialogCancel><AlertDialogAction disabled={busy} onClick={event=>{event.preventDefault();void send()}}>{busy?"Enviando…":"Confirmar pedido"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></div>;
}

function CasesList({rows}:{rows:CaseRow[]}){return <div className="space-y-2">{rows.map(row=><article key={row.id} className="pdmc-surface flex items-center gap-3 rounded-2xl border bg-card p-4"><span className={`grid size-10 shrink-0 place-items-center rounded-xl ${row.resuelto?"bg-success-100 text-success-700 dark:bg-success-950/40 dark:text-success-200":"bg-warning-100 text-warning-800 dark:bg-warning-950/40 dark:text-warning-200"}`}><PackageSearch className="size-5"/></span><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><p className="truncate font-semibold">{row.tipoError}</p>{row.claveCruce&&<Badge variant="outline">Cruce</Badge>}</div><p className="truncate text-xs text-muted-foreground">{row.codigoBarra} · #{row.transferencia} · {dateTime(row.createdAt)}</p></div><Badge className={row.resuelto?"bg-success-100 text-success-800 dark:bg-success-950/40 dark:text-success-200":"bg-warning-100 text-warning-900 dark:bg-warning-950/40 dark:text-warning-200"}>{row.resuelto?"Solucionado":"Pendiente"}</Badge></article>)}</div>}
function ReportHistory({rows}:{rows:ReportRow[]}){const [expanded,setExpanded]=useState<string|null>(null);return <div className="space-y-2">{rows.map(row=>{const open=expanded===row.id,expandable=!row.sinIncidencias&&row.detalles.length>0;return <article key={row.id} className="pdmc-surface overflow-hidden rounded-2xl border bg-card shadow-sm"><button type="button" className={`flex w-full items-center gap-3 p-4 text-left ${expandable?"transition hover:bg-muted/40":"cursor-default"}`} disabled={!expandable} aria-expanded={expandable?open:undefined} onClick={()=>expandable&&setExpanded(open?null:row.id)}><span className={`grid size-11 shrink-0 place-items-center rounded-xl ${row.sinIncidencias?"bg-success-100 text-success-700 dark:bg-success-950/40 dark:text-success-200":"bg-warning-100 text-warning-800 dark:bg-warning-950/40 dark:text-warning-200"}`}>{row.sinIncidencias?<Check className="size-5"/>:<AlertTriangle className="size-5"/>}</span><span className="min-w-0 flex-1"><span className="block font-mono font-bold">Transferencia #{row.transferencia}</span><span className="block truncate text-xs text-muted-foreground">{row.tienda} · {dateTime(row.createdAt)}</span></span><Badge className={!row.finalizado?"bg-info-100 text-info-800 dark:bg-info-950/40 dark:text-info-200":row.sinIncidencias?"bg-success-100 text-success-800 dark:bg-success-950/40 dark:text-success-200":row.detalles.length?"bg-warning-100 text-warning-900 dark:bg-warning-950/40 dark:text-warning-200":"bg-muted text-muted-foreground"}>{!row.finalizado?"En progreso":row.sinIncidencias?"Sin inconsistencias":row.detalles.length?"Con inconsistencias":"Reportada anteriormente"}</Badge>{expandable&&<ChevronDown className={`size-5 shrink-0 text-muted-foreground transition ${open?"rotate-180":""}`}/>}</button>{open&&<div className="border-t bg-muted/20 p-4"><p className="mb-3 text-xs font-semibold uppercase tracking-widest text-primary">Productos con inconsistencias</p><div className="space-y-3">{row.detalles.map(detail=><div key={detail.id} className="rounded-xl border bg-background p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="font-mono text-sm font-bold">{detail.codigoBarra}</p><p className="mt-1 text-sm font-medium">{detail.descripcion||detail.tipoError}</p></div><Badge variant="outline">{detail.cantidad} unidad(es)</Badge></div><div className="mt-3 grid gap-1 text-xs text-muted-foreground"><p><b className="text-foreground">Inconsistencia:</b> {detail.tipoError}</p>{detail.motivo&&<p><b className="text-foreground">Motivo:</b> {detail.motivo.replaceAll("_"," ")}</p>}{detail.submotivo&&<p><b className="text-foreground">Detalle:</b> {detail.submotivo.replaceAll("_"," ")}</p>}{detail.codigoBarraTransferencia&&<p><b className="text-foreground">Código esperado:</b> {detail.codigoBarraTransferencia}</p>}{detail.cantidadPaquete&&<p><b className="text-foreground">Cantidad del paquete:</b> {detail.cantidadPaquete}</p>}{detail.detalle&&<p><b className="text-foreground">Observación de tienda:</b> {detail.detalle}</p>}{detail.observacionAdmin&&<p className="mt-2 rounded-lg bg-primary/8 p-2 text-foreground"><b>Observación administrativa:</b> {detail.observacionAdmin}</p>}<p><b className="text-foreground">Estado:</b> {detail.resuelto?"Solucionado":"Pendiente"}</p></div></div>)}</div></div>}</article>})}</div>}
function CasesView({rows,reports}:{rows:CaseRow[];reports:ReportRow[]}){const cutoff=Date.UTC(2026,7,1),previous=reports.filter(row=>new Date(row.createdAt).getTime()<cutoff),monthly=new Map<string,ReportRow[]>();for(const row of reports){const value=new Date(row.createdAt);if(value.getTime()<cutoff)continue;const key=`${value.getUTCFullYear()}-${String(value.getUTCMonth()+1).padStart(2,"0")}`,group=monthly.get(key)??[];group.push(row);monthly.set(key,group)}const groups=[...monthly.entries()].sort(([a],[b])=>b.localeCompare(a));return <div className="space-y-6"><section className="store-section-head"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">Historial de recepción</p><h1 className="mt-1 text-2xl font-black sm:text-3xl">Transferencias reportadas</h1><p className="mt-2 text-sm text-muted-foreground">Consulta cada reporte y despliega las diferencias registradas por producto.</p></div><span className="grid size-14 place-items-center rounded-2xl bg-info-100 text-2xl font-black text-info-800 dark:bg-info-950/50 dark:text-info-200">{reports.length}</span></section>{groups.map(([key,items],index)=><details key={key} open={index===0} className="group overflow-hidden rounded-3xl border bg-card shadow-sm"><summary className="flex cursor-pointer list-none items-center gap-3 p-5 font-bold capitalize transition hover:bg-muted/30"><span className="flex-1">{new Intl.DateTimeFormat("es-VE",{month:"long",year:"numeric",timeZone:"UTC"}).format(new Date(`${key}-01T00:00:00Z`))}</span><Badge variant="outline">{items.length} reportes</Badge><ChevronDown className="size-5 text-muted-foreground transition group-open:rotate-180"/></summary><div className="border-t bg-muted/10 p-3 sm:p-4"><ReportHistory rows={items}/></div></details>)}{previous.length>0&&<details className="group overflow-hidden rounded-3xl border bg-card shadow-sm"><summary className="flex cursor-pointer list-none items-center gap-3 p-5 font-bold"><span className="flex-1">Historial anterior</span><Badge variant="outline">{previous.length} reportes</Badge><ChevronDown className="size-5 text-muted-foreground transition group-open:rotate-180"/></summary><div className="border-t bg-muted/10 p-3 sm:p-4"><ReportHistory rows={previous}/></div></details>}{!reports.length&&<div className="rounded-3xl border border-dashed bg-card/60 p-12 text-center"><ClipboardList className="mx-auto size-8 text-muted-foreground"/><p className="mt-3 font-semibold">Aún no hay transferencias reportadas</p></div>}{rows.length>0&&<section className="pdmc-surface rounded-3xl border bg-card p-5 shadow-sm"><div className="mb-4"><p className="text-xs font-bold uppercase tracking-[.15em] text-primary">Seguimiento abierto</p><h2 className="mt-1 text-lg font-bold">Inconsistencias recientes</h2></div><CasesList rows={rows}/></section>}</div>}

function ReportProgress({step,last,cross}:{step:number;last:number;cross:boolean}){const labels=cross?["Producto","Motivo","Cruce","Cantidad","Confirmar"]:["Producto","Motivo","Cantidad","Confirmar"];return <div className={`grid gap-1 sm:gap-2 ${cross?"grid-cols-5":"grid-cols-4"}`}>{labels.map((label,index)=>{const position=cross?index:Math.min(index,last),active=position===step,complete=position<step;return <div key={label} className={`rounded-xl px-2 py-2 text-center transition ${active?"bg-white text-brand-deep shadow-sm":complete?"bg-white/15 text-white":"text-white/45"}`}><span className={`mx-auto mb-1 grid size-5 place-items-center rounded-full text-[10px] font-black ${active?"bg-primary text-primary-foreground":complete?"bg-success-300 text-success-950 dark:text-success-200":"border border-white/25"}`}>{complete?<Check className="size-3"/>:index+1}</span><span className="hidden text-[10px] font-bold sm:block">{label}</span></div>})}</div>}

function TransferPicker({rows,value,disabled,onChange}:{rows:TransferRow[];value:string;disabled:boolean;onChange:(value:string)=>void}){return <div className="space-y-3"><div className="flex items-center justify-between"><div><p className="text-sm font-bold">Seleccione la transferencia</p><p className="text-xs text-muted-foreground">El reporte quedará vinculado a esta recepción.</p></div><Badge variant="outline">{rows.length} pendientes</Badge></div><div className="grid max-h-72 gap-2 overflow-y-auto pr-1 sm:grid-cols-2">{rows.map(item=>{const selected=value===item.id;return <button type="button" key={item.id} disabled={disabled} onClick={()=>onChange(item.id)} className={`relative overflow-hidden rounded-2xl border p-4 text-left transition ${selected?"border-primary bg-primary/[.07] shadow-md ring-1 ring-primary/20":"bg-background hover:border-primary/35 hover:bg-muted/25"}`}><div className="flex items-start justify-between gap-2"><span className="font-mono text-lg font-black">#{item.id}</span><span className={`grid size-6 place-items-center rounded-full border ${selected?"border-primary bg-primary text-primary-foreground":"text-transparent"}`}><Check className="size-3.5"/></span></div><p className="mt-2 text-xs font-bold uppercase tracking-wider text-primary">{transferTypeLabel[item.type]}</p><div className="mt-3 flex items-center justify-between text-xs text-muted-foreground"><span>{item.units.toLocaleString("es-VE")} unidades</span>{item.date&&<span>{item.date}</span>}</div>{item.description&&<p className="mt-2 line-clamp-2 text-xs text-muted-foreground">{item.description}</p>}</button>})}</div>{!rows.length&&<div className="rounded-2xl border border-dashed p-6 text-center text-sm text-muted-foreground">No hay transferencias pendientes para reportar.</div>}</div>}

function ReasonContent({id,label}:{id:StoreReportReason;label:string}){const Icon=id==="FALTANTE"?PackageMinus:id==="SOBRANTE"?PackagePlus:id==="CRUCE"?Repeat2:id==="DANADO"?AlertTriangle:CircleHelp;const detail={FALTANTE:"Faltan unidades o mercancía",SOBRANTE:"Llegaron unidades adicionales",CRUCE:"Llegó un producto por otro",DANADO:"Producto con daño físico",VENCIDO:"Producto fuera de vigencia",OTRO:"Una situación diferente"}[id];return <span className="flex items-center gap-3"><span className="grid size-10 shrink-0 place-items-center rounded-xl bg-current/10"><Icon className="size-5"/></span><span><span className="block font-bold">{label}</span><span className="mt-0.5 block text-xs font-normal opacity-70">{detail}</span></span></span>}

function ReportFlow({data,done,openUnknown,drafts,setDrafts,reviewRequest}:{data:Dashboard;done:(finish:boolean)=>Promise<void>;openUnknown:(seed:UnknownSeed)=>void;drafts:ReportDraft[];setDrafts:React.Dispatch<React.SetStateAction<ReportDraft[]>>;reviewRequest:number}){
  const firstStore=data.stores[0]?.id??"",firstTransfer=data.transfers.find(item=>item.tiendaId===firstStore)?.id??"";
  const [step,setStep]=useState(0),[storeId,setStoreId]=useState(firstStore),[transfer,setTransfer]=useState(firstTransfer),[code,setCode]=useState(""),[product,setProduct]=useState<Product|null>(null),[reason,setReason]=useState<StoreReportReason|null>(null),[subreason,setSubreason]=useState<StoreReportSubreason|null>(null),[other,setOther]=useState(""),[crossCode,setCrossCode]=useState(""),[crossProduct,setCrossProduct]=useState<Product|null>(null),[quantity,setQuantity]=useState(1),[busy,setBusy]=useState(false),[error,setError]=useState(""),[scanning,setScanning]=useState<"original"|"cross"|null>(null),[reviewing,setReviewing]=useState(reviewRequest>0),[unknownCode,setUnknownCode]=useState(false),[editingId,setEditingId]=useState<string|null>(null);
  const transfers=useMemo(()=>data.transfers.filter(item=>item.tiendaId===storeId),[data.transfers,storeId]),cross=reason==="CRUCE",last=cross?4:3,progress=(step+1)/(last+1)*100;
  const lookup=async(value:string,target:"original"|"cross")=>{setBusy(true);setError("");if(target==="original")setUnknownCode(false);try{const item=await api<Product>(`?accion=producto&codigo=${encodeURIComponent(value)}`);if(target==="original"){setCode(item.codigoBarra);setProduct(item)}else{setCrossCode(item.codigoBarra);setCrossProduct(item)}}catch(e){if(target==="original"&&e instanceof StoreApiError&&e.status===404){setProduct(null);setUnknownCode(true);setError("")}else setError(e instanceof Error?e.message:"Código no encontrado.")}finally{setBusy(false)}};
  const scan=useCallback((value:string)=>{const target=scanning;if(!target)return;setScanning(null);void lookup(value,target)},[scanning]);
  const canNext=step===0?Boolean(storeId&&transfer&&product):step===1?Boolean(reason&&(reason!=="OTRO"||other.trim())&&(!["FALTANTE","SOBRANTE"].includes(reason)||subreason)):step===2&&cross?Boolean(crossProduct&&crossProduct.id!==product?.id):step===(cross?3:2)?quantity>0:true;
  const resetItem=()=>{setStep(0);setCode("");setProduct(null);setUnknownCode(false);setReason(null);setSubreason(null);setOther("");setCrossCode("");setCrossProduct(null);setQuantity(1);setEditingId(null)};
  const codes=(item:ReportDraft)=>item.kind==="PRODUCTO"?[item.product.codigoBarra,...(item.crossProduct?[item.crossProduct.codigoBarra]:[])]:[item.code];
  const addDraft=(review:boolean)=>{if(!product||!reason)return;const used=new Set(drafts.filter(item=>item.solicitudId!==editingId).flatMap(codes)),incoming=[product.codigoBarra,...(crossProduct?[crossProduct.codigoBarra]:[])];if(incoming.some(value=>used.has(value))){setError("Cada código de barras solo puede tener una inconsistencia dentro de la transferencia.");return}const next:ProductDraft={kind:"PRODUCTO",solicitudId:editingId??crypto.randomUUID(),product,crossProduct,motivo:reason,submotivo:subreason,detalleOtro:other,cantidad:quantity};setDrafts(current=>editingId?current.map(item=>item.solicitudId===editingId?next:item):[...current,next]);resetItem();setReviewing(review)};
  const editDraft=(item:ReportDraft)=>{if(item.kind==="CODIGO_NO_REGISTRADO"){openUnknown({storeId,transfer,code:item.code,editId:item.solicitudId});return}setCode(item.product.codigoBarra);setProduct(item.product);setReason(item.motivo);setSubreason(item.submotivo);setOther(item.detalleOtro);setCrossCode(item.crossProduct?.codigoBarra??"");setCrossProduct(item.crossProduct);setQuantity(item.cantidad);setEditingId(item.solicitudId);setReviewing(false);setStep(0);setError("")};
  const confirm=async()=>{setBusy(true);setError("");try{for(const item of drafts){if(item.kind==="PRODUCTO")await api("?accion=reportar",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({solicitudId:item.solicitudId,tiendaId:storeId,transferencia:transfer,codigoBarra:item.product.codigoBarra,codigoCruce:item.crossProduct?.codigoBarra,motivo:item.motivo,submotivo:item.submotivo||undefined,detalleOtro:item.detalleOtro||undefined,cantidad:item.cantidad})});else await api("?accion=codigo-no-inventario",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({solicitudId:item.solicitudId,tiendaId:storeId,transferencia:transfer,codigoBarraNoInventario:item.code,motivo:item.reason,codigoBarraTransferencia:item.reason==="CODIGO_MEZCLADO_PAQUETE"?item.expectedCode:undefined,cantidadPaquete:item.reason==="CODIGO_MEZCLADO_PAQUETE"?item.packageQuantity:undefined,cantidadCodigoNoInventario:item.reason==="CODIGO_MEZCLADO_PAQUETE"?item.unknownQuantity:undefined,cantidad:item.reason==="OTRA_PRENDA"?item.quantity:undefined,detalle:item.reason!=="CODIGO_MEZCLADO_PAQUETE"?item.detail:undefined})})}await api("?accion=finalizar-con-incidencias",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({solicitudId:crypto.randomUUID(),tiendaId:storeId,transferencia:transfer})});toast.success(`Transferencia reportada con ${drafts.length} inconsistencia(s).`);await done(true)}catch(e){setError(e instanceof Error?e.message:"No se pudo confirmar el reporte.")}finally{setBusy(false)}};
  if(reviewing)return <div className="mx-auto max-w-3xl space-y-5"><div><p className="text-xs font-semibold uppercase tracking-widest text-primary">Vista previa</p><h1 className="mt-1 text-2xl font-bold">Revise todas las inconsistencias</h1><p className="mt-2 text-sm text-muted-foreground">Transferencia #{transfer} · {drafts.length} registro(s). Todavía no se ha enviado nada.</p></div><div className="space-y-3">{drafts.map(item=>{const unknown=item.kind==="CODIGO_NO_REGISTRADO";const label=unknown?"Código no registrado":STORE_REPORT_REASONS.find(option=>option[0]===item.motivo)?.[1];const itemCode=unknown?item.code:item.product.codigoBarra;const amount=unknown?(item.reason==="CODIGO_MEZCLADO_PAQUETE"?item.unknownQuantity:item.quantity):item.cantidad;return <article key={item.solicitudId} className="pdmc-surface rounded-2xl border bg-card p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-mono font-bold">{itemCode}</p><p className="text-sm">{unknown?"Producto fuera del inventario":item.product.descripcion||item.product.referencia||"Producto"}</p></div><Badge variant="outline">{label}</Badge></div><p className="mt-3 text-sm"><b>{amount}</b> unidad(es)</p>{unknown&&<p className="mt-2 text-sm">{UNKNOWN_BARCODE_REASONS.find(option=>option[0]===item.reason)?.[1]}{item.expectedCode?" · Código esperado "+item.expectedCode:""}</p>}{!unknown&&item.crossProduct&&<p className="mt-2 text-sm">Cruce con <span className="font-mono font-semibold">{item.crossProduct.codigoBarra}</span></p>}{(unknown?item.detail:item.detalleOtro)&&<p className="mt-2 text-sm text-muted-foreground">{unknown?item.detail:item.detalleOtro}</p>}<div className="mt-3 flex gap-2"><Button size="sm" variant="outline" disabled={busy} onClick={()=>editDraft(item)}><Edit3/>Editar</Button><Button size="sm" variant="ghost" className="text-destructive hover:text-destructive" disabled={busy} onClick={()=>setDrafts(current=>current.filter(draft=>draft.solicitudId!==item.solicitudId))}><Trash2/>Eliminar</Button></div></article>})}</div>{error&&<p role="alert" className="rounded-xl bg-danger-50 p-3 text-sm text-danger-800 dark:bg-danger-950/40 dark:text-danger-200">{error}</p>}<div className="flex flex-wrap gap-2"><Button variant="outline" disabled={busy} onClick={()=>{setReviewing(false);resetItem()}}><Plus/>Agregar otra</Button><Button className="ml-auto" disabled={busy||!drafts.length} onClick={()=>void confirm()}>{busy?"Enviando…":"Confirmar y enviar"}<Check/></Button></div></div>;
  return <div className="mx-auto max-w-3xl space-y-5"><section className="store-report-head"><div className="relative z-10 grid gap-5 sm:grid-cols-[1fr_330px] sm:items-end"><div><p className="text-[11px] font-bold uppercase tracking-[.18em] text-brand-mist">{editingId?"Editar inconsistencia":"Nuevo reporte"}</p><h1 className="mt-2 text-2xl font-black text-white sm:text-3xl">{["Elija transferencia y producto","¿Qué ocurrió?",cross?"Identifique el producto cruzado":"Indique la cantidad",cross?"Indique la cantidad":"Revise el registro","Revise el registro"][step]}</h1><p className="mt-2 text-sm text-white/60">Complete un producto a la vez. Podrá revisar todos antes de enviar.</p></div><ReportProgress step={step} last={last} cross={cross}/></div>{drafts.length>0&&<div className="relative z-10 mt-4 flex flex-wrap items-center justify-between gap-2 rounded-xl bg-success-300/15 px-3 py-2 text-xs font-bold text-success-100"><span className="flex items-center gap-2"><Check className="size-4"/>{drafts.length} inconsistencia(s) guardadas en el borrador</span><button type="button" className="underline underline-offset-2" onClick={()=>setReviewing(true)}>Revisar borrador</button></div>}<Progress className="relative z-10 mt-4 h-1 bg-white/15" value={progress}/></section><section className="store-report-card p-5 sm:p-7">{step===0&&<div className="space-y-5">{data.stores.length>1&&<label className="grid gap-2 text-sm font-semibold">Tienda<Select disabled={drafts.length>0} value={storeId} onValueChange={value=>{setStoreId(value);setTransfer(data.transfers.find(item=>item.tiendaId===value)?.id??"")}}><SelectTrigger className="w-full"><SelectValue/></SelectTrigger><SelectContent>{data.stores.map(item=><SelectItem key={item.id} value={item.id}>{item.nombre}</SelectItem>)}</SelectContent></Select></label>}<TransferPicker rows={transfers} value={transfer} disabled={drafts.length>0} onChange={setTransfer}/><CodeInput label="Código de barras" value={code} setValue={value=>{setCode(value);setProduct(null);setUnknownCode(false)}} product={product} busy={busy} scan={()=>setScanning("original")} search={()=>void lookup(code,"original")}/>{unknownCode&&<div className="rounded-2xl border border-warning-200 bg-warning-50 p-4 text-warning-950 dark:border-warning-800 dark:bg-warning-950/40 dark:text-warning-200"><p className="text-sm font-semibold">No encontramos este código en el inventario.</p><Button type="button" variant="outline" className="mt-3 w-full border-warning-300 bg-white dark:border-warning-800" onClick={()=>openUnknown({storeId,transfer,code})}><Barcode/>Reportar código no registrado</Button></div>}</div>}{step===1&&<div className="grid gap-3 sm:grid-cols-2">{STORE_REPORT_REASONS.map(([id,label])=><button key={id} onClick={()=>{setReason(id);setSubreason(null)}} className={`rounded-2xl border-2 p-5 text-left font-semibold shadow-sm transition hover:-translate-y-0.5 ${reason===id?({FALTANTE:"border-danger-500 bg-danger-50 text-danger-800 dark:bg-danger-950/40 dark:text-danger-200",SOBRANTE:"border-info-500 bg-info-50 text-info-800 dark:bg-info-950/40 dark:text-info-200",CRUCE:"border-violet-500 bg-violet-50 text-violet-800",DANADO:"border-warning-500 bg-warning-50 text-warning-900 dark:bg-warning-950/40 dark:text-warning-200",VENCIDO:"border-orange-500 bg-orange-50 text-orange-900",OTRO:"border-muted-foreground bg-muted text-foreground"} as const)[id]:"border-border bg-card hover:border-primary/35 hover:shadow-md"}`}><ReasonContent id={id} label={label}/></button>)}{(reason==="FALTANTE"||reason==="SOBRANTE")&&<div className="grid gap-2 sm:col-span-2"><p className="text-sm font-semibold">Detalle de la diferencia</p>{STORE_REPORT_SUBREASONS[reason].map(([id,label])=><button type="button" key={id} onClick={()=>setSubreason(id)} className={`rounded-xl border-2 p-4 text-left text-sm font-medium transition ${subreason===id?"border-primary bg-primary/10 text-primary":"border-border bg-background hover:border-primary/30"}`}>{label}</button>)}</div>}{reason==="OTRO"&&<Textarea className="sm:col-span-2" aria-label="Detalle del motivo" placeholder="Describa el motivo" value={other} onChange={e=>setOther(e.target.value)}/>}</div>}{step===2&&cross&&<CodeInput label="Producto encontrado físicamente" value={crossCode} setValue={value=>{setCrossCode(value);setCrossProduct(null)}} product={crossProduct} busy={busy} scan={()=>setScanning("cross")} search={()=>void lookup(crossCode,"cross")}/>} {step===(cross?3:2)&&<div><p className="mb-4 text-sm font-semibold">Cantidad de unidades</p><div className="mb-4 grid grid-cols-4 gap-2">{[1,2,6,12].map(value=><Button key={value} variant={quantity===value?"default":"outline"} className="h-14 text-lg" onClick={()=>setQuantity(value)}>{value}</Button>)}</div><Input aria-label="Cantidad" type="number" min={1} step={1} value={quantity} onChange={e=>setQuantity(Number(e.target.value))}/></div>}{step===last&&<Confirmation store={data.stores.find(item=>item.id===storeId)!} transfer={transfer} product={product!} crossProduct={crossProduct} reason={reason!} other={other} quantity={quantity}/>} {error&&<p role="alert" className="mt-4 rounded-xl bg-danger-50 p-3 text-sm text-danger-800 dark:bg-danger-950/40 dark:text-danger-200">{error}</p>}<div className="mt-6 flex gap-2"><Button variant="outline" disabled={busy||step===0} onClick={()=>setStep(value=>value-1)}><ArrowLeft/>Atrás</Button>{step<last?<Button className="ml-auto" disabled={busy||!canNext} onClick={()=>setStep(value=>value+1)}>Continuar<ArrowRight/></Button>:<div className="ml-auto flex flex-wrap justify-end gap-2"><Button variant="outline" disabled={busy} onClick={()=>addDraft(false)}><Plus/>{editingId?"Guardar cambios":"Agregar otro código"}</Button><Button disabled={busy} onClick={()=>addDraft(true)}>{editingId?"Guardar y revisar":"Ver resumen final"}<ArrowRight/></Button></div>}</div></section>{scanning&&<Scanner onCode={scan} close={()=>setScanning(null)}/>}</div>;
}

function UnknownCodeFlow({data,seed,backToReport,reviewReport,drafts,setDrafts}:{data:Dashboard;seed:UnknownSeed;backToReport:()=>void;reviewReport:()=>void;drafts:ReportDraft[];setDrafts:React.Dispatch<React.SetStateAction<ReportDraft[]>>}){
  const editing=seed.editId?drafts.find((item):item is UnknownDraft=>item.kind==="CODIGO_NO_REGISTRADO"&&item.solicitudId===seed.editId):undefined;
  const [storeId,setStoreId]=useState(seed.storeId),[transfer,setTransfer]=useState(seed.transfer),[code,setCode]=useState(editing?.code??seed.code),[reason,setReason]=useState<UnknownBarcodeReason>(editing?.reason??"CODIGO_MEZCLADO_PAQUETE"),[expectedCode,setExpectedCode]=useState(editing?.expectedCode??""),[packageQuantity,setPackageQuantity]=useState(editing?.packageQuantity??1),[unknownQuantity,setUnknownQuantity]=useState(editing?.unknownQuantity??1),[quantity,setQuantity]=useState(editing?.quantity??1),[detail,setDetail]=useState(editing?.detail??""),[busy,setBusy]=useState(false),[error,setError]=useState("");
  const transfers=data.transfers.filter(item=>item.tiendaId===storeId);
  const valid=Boolean(storeId&&transfer&&code.trim()&&(reason!=="CODIGO_MEZCLADO_PAQUETE"||(expectedCode.trim()&&packageQuantity>0&&unknownQuantity>0&&unknownQuantity<=packageQuantity))&&(reason!=="OTRA_PRENDA"||(quantity>0&&detail.trim()))&&(reason!=="OTRO"||detail.trim()));
  const build=():UnknownDraft=>({kind:"CODIGO_NO_REGISTRADO",solicitudId:editing?.solicitudId??crypto.randomUUID(),code:code.trim(),reason,expectedCode:reason==="CODIGO_MEZCLADO_PAQUETE"?expectedCode.trim():"",packageQuantity,unknownQuantity,quantity,detail:reason==="CODIGO_MEZCLADO_PAQUETE"?"":detail.trim()});
  const save=(review:boolean)=>{setBusy(true);setError("");try{const item=build();const duplicate=drafts.some(existing=>existing.solicitudId!==item.solicitudId&&(existing.kind==="PRODUCTO"?[existing.product.codigoBarra,existing.crossProduct?.codigoBarra]:[existing.code]).filter(Boolean).includes(item.code));if(duplicate)throw new Error("Este código de barras ya está incluido en el reporte.");setDrafts(current=>editing?current.map(existing=>existing.solicitudId===editing.solicitudId?item:existing):[...current,item]);toast.success(editing?"Inconsistencia actualizada.":"Inconsistencia agregada al borrador.");if(review)reviewReport();else backToReport()}catch(e){setError(e instanceof Error?e.message:"No se pudo guardar el reporte.")}finally{setBusy(false)}};
  return <div className="mx-auto max-w-2xl space-y-5"><section className="store-section-head"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-primary">{editing?"Editar inconsistencia":"Reporte especial"}</p><h1 className="mt-1 text-2xl font-black">Código no registrado</h1><p className="mt-2 text-sm text-muted-foreground">Puede guardarlo, seguir agregando productos o pasar al resumen para revisar todo antes de confirmar.</p></div><span className="grid size-14 place-items-center rounded-2xl bg-warning-100 text-warning-800 dark:bg-warning-950/40 dark:text-warning-200"><Barcode className="size-7"/></span></section><section className="pdmc-surface space-y-4 rounded-3xl border bg-card p-5 shadow-sm sm:p-7">{data.stores.length>1&&<label className="grid gap-2 text-sm font-semibold">Tienda<Select disabled={drafts.length>0} value={storeId} onValueChange={value=>{setStoreId(value);setTransfer(data.transfers.find(item=>item.tiendaId===value)?.id??"")}}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{data.stores.map(item=><SelectItem key={item.id} value={item.id}>{item.nombre}</SelectItem>)}</SelectContent></Select></label>}<label className="grid gap-2 text-sm font-semibold">Transferencia<Select disabled={drafts.length>0} value={transfer} onValueChange={setTransfer}><SelectTrigger><SelectValue placeholder="Seleccione"/></SelectTrigger><SelectContent>{transfers.map(item=><SelectItem key={item.id} value={item.id}>#{item.id} · {transferTypeLabel[item.type]}</SelectItem>)}</SelectContent></Select></label><label className="grid gap-2 text-sm font-semibold">Código que no existe en inventario<Input value={code} onChange={e=>setCode(e.target.value)} inputMode="numeric"/></label><div className="grid gap-2">{UNKNOWN_BARCODE_REASONS.map(([id,label])=><button type="button" key={id} onClick={()=>setReason(id)} className={"rounded-xl border p-3 text-left text-sm font-semibold "+(reason===id?"border-primary bg-primary/10":"")}>{label}</button>)}</div>{reason==="CODIGO_MEZCLADO_PAQUETE"&&<div className="grid gap-3 sm:grid-cols-2"><label className="grid gap-1 text-sm font-semibold sm:col-span-2">Código que debía llegar en la transferencia<Input value={expectedCode} onChange={e=>setExpectedCode(e.target.value)} inputMode="numeric"/></label><label className="grid gap-1 text-sm font-semibold">Cantidad total del paquete<Input type="number" min={1} value={packageQuantity} onChange={e=>setPackageQuantity(Number(e.target.value))}/></label><label className="grid gap-1 text-sm font-semibold">Cantidad con código no existente<Input type="number" min={1} max={packageQuantity} value={unknownQuantity} onChange={e=>setUnknownQuantity(Number(e.target.value))}/></label></div>}{reason==="OTRA_PRENDA"&&<label className="grid gap-1 text-sm font-semibold">Cantidad<Input type="number" min={1} value={quantity} onChange={e=>setQuantity(Number(e.target.value))}/></label>}{reason!=="CODIGO_MEZCLADO_PAQUETE"&&<label className="grid gap-1 text-sm font-semibold">Explicación<Textarea maxLength={500} value={detail} onChange={e=>setDetail(e.target.value)} placeholder="Describa lo recibido"/></label>}{error&&<p role="alert" className="rounded-xl bg-danger-50 p-3 text-sm text-danger-800 dark:bg-danger-950/40 dark:text-danger-200">{error}</p>}<div className="grid gap-2 sm:grid-cols-2"><Button variant="outline" disabled={busy} onClick={backToReport}><ArrowLeft/>Volver sin guardar</Button><Button disabled={busy||!valid} onClick={()=>save(false)}>{busy?"Guardando…":editing?"Guardar cambios":"Guardar y agregar otra"}<Plus/></Button><Button className="sm:col-span-2" variant="secondary" disabled={busy||!valid} onClick={()=>save(true)}><ArrowRight/>Ver resumen final</Button></div></section></div>;
}
function CodeInput({label,value,setValue,product,busy,scan,search}:{label:string;value:string;setValue:(value:string)=>void;product:Product|null;busy:boolean;scan:()=>void;search:()=>void}){return <div className="space-y-4"><div><p className="text-sm font-bold">{label}</p><p className="mt-0.5 text-xs text-muted-foreground">Escanee la etiqueta o escriba el código completo.</p></div><div className="relative"><Barcode className="pointer-events-none absolute left-4 top-1/2 z-10 size-5 -translate-y-1/2 text-primary"/><Input aria-label={label} inputMode="numeric" autoComplete="off" value={value} onChange={e=>setValue(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&value.trim()&&!busy){e.preventDefault();search()}}} placeholder="Código de barras" className="h-14 rounded-2xl border-primary/25 bg-background pl-12 pr-16 font-mono text-lg font-bold tracking-wide shadow-sm hover:border-primary/45 focus-visible:border-primary focus-visible:bg-background dark:bg-background/70"/><Button type="button" variant="ghost" size="icon" className="absolute right-1.5 top-1.5 size-11 rounded-xl bg-muted/70 text-primary hover:bg-primary hover:text-primary-foreground" onClick={scan} aria-label="Escanear código"><Camera/></Button></div><Button type="button" className="h-12 w-full rounded-xl font-bold" disabled={busy||!value.trim()} onClick={search}>{busy?<RefreshCw className="animate-spin"/>:<Search/>}{busy?"Buscando en inventario…":"Buscar producto"}</Button>{product&&<div className="overflow-hidden rounded-2xl border border-success-200 bg-gradient-to-br from-success-50 to-brand-50 text-success-950 shadow-sm dark:border-success-900 dark:from-success-950/40 dark:to-brand-950/30 dark:text-success-100"><div className="flex items-center gap-3 border-b border-success-200/70 p-4 dark:border-success-900"><span className="grid size-10 place-items-center rounded-xl bg-success-600 text-white"><Check className="size-5"/></span><div><p className="text-xs font-bold uppercase tracking-wider opacity-65">Producto encontrado</p><p className="font-mono text-sm font-black">{product.codigoBarra}</p></div></div><div className="p-4"><p className="font-bold">{product.descripcion||product.referencia||"Producto sin descripción"}</p><div className="mt-2 flex flex-wrap gap-2"><Badge variant="outline" className="border-success-300 bg-white/50 dark:border-success-800 dark:bg-black/10">{product.marca||"Sin marca"}</Badge>{product.referencia&&<Badge variant="outline" className="border-success-300 bg-white/50 dark:border-success-800 dark:bg-black/10">Ref. {product.referencia}</Badge>}</div></div></div>}</div>}

function Confirmation({store,transfer,product,crossProduct,reason,other,quantity}:{store:StoreLocation;transfer:string;product:Product;crossProduct:Product|null;reason:StoreReportReason;other:string;quantity:number}){const label=STORE_REPORT_REASONS.find(item=>item[0]===reason)?.[1];return <div className="space-y-4"><div className="rounded-2xl border bg-muted/25 p-4"><p className="text-[10px] font-bold uppercase tracking-[.15em] text-muted-foreground">Se agregará a la vista previa</p><div className="mt-3 flex flex-wrap items-center gap-2"><Badge>Transferencia #{transfer}</Badge><Badge variant="outline">{store.nombre}</Badge><Badge variant="outline">{label}</Badge></div>{other&&<p className="mt-3 text-sm text-muted-foreground">{other}</p>}</div>{reason==="CRUCE"?<div className="space-y-3"><ResultLine tone="rose" title="Faltante" product={product} quantity={quantity}/><ResultLine tone="sky" title="Sobrante" product={crossProduct!} quantity={quantity}/></div>:<ResultLine tone={reason==="SOBRANTE"?"sky":"rose"} title={label!} product={product} quantity={quantity}/>}</div>}
function ResultLine({tone,title,product,quantity}:{tone:"rose"|"sky";title:string;product:Product;quantity:number}){return <div className={`rounded-2xl border p-4 ${tone==="rose"?"border-danger-200 bg-danger-50 text-danger-950 dark:border-danger-800 dark:bg-danger-950/40 dark:text-danger-200":"border-info-200 bg-info-50 text-info-950 dark:border-info-800 dark:bg-info-950/40 dark:text-info-200"}`}><div className="flex justify-between gap-3"><b>{title}</b><b>{quantity} unidades</b></div><p className="mt-2 font-mono text-xs">{product.codigoBarra}</p><p className="mt-1 text-sm">{product.descripcion||product.referencia||"Producto"}</p></div>}













